output_detail.transcript_schema:
{
    "transcript_schema": {
        "description": "Summary parameters to understand how the call went",
        "properties": {
            "call_language": {
                "description": "Identify which language the call was mostly conducted in. Reply with one of: \"taglish\", \"english\".",
                "type": "string"
            },
            "faq_answered": {
                "description": "Determine if at least one caller question was answered from the knowledge base. Reply with \"True\" or \"False\".",
                "type": "boolean"
            },
            "human_agent_requested": {
                "description": "Determine if the caller reported a serious matter, asked for an account action, or explicitly asked for a human agent at any point. Reply with \"True\" or \"False\".",
                "type": "boolean"
            },
            "human_agent_request_reason": {
                "description": "If human_agent_requested is True, identify why. Reply with one of: \"human_request\", \"serious_matter\", \"account_action\", \"none\".",
                "type": "string"
            },
            "sentiment": {
                "description": "Identify the caller's overall sentiment. Reply with one of: \"happy\", \"neutral\", \"angry\".",
                "type": "string"
            }
        },
        "required": [
            "faq_answered",
            "sentiment"
        ],
        "title": "call_analysis",
        "type": "object"
    },
    "transcript_summary_model_provider_config": null
}

